#!/usr/bin/env python3
from pathlib import Path
import json,zipfile,hashlib
R=Path(__file__).resolve().parents[1]; inv=json.loads((R/'reports/required-report-inventory.json').read_text())
files=[R/'reports'/x['report'] for x in inv['reports']]
files += [R/'EXPERT_REVIEW_REQUIRED.md',R/'reports/2026-11-13-expert-review-register.csv',R/'reports/2026-11-13-priority-proposal-package-validation.json',R/'PROGRESS.json',R/'STATUS.md',R/'MASTER_PLAN.md',R/'GOAL_ADDENDUM.md',R/'scripts/validate_priority_proposal_shells.py']
for d in sorted((R/'proposals').glob('*')):
 if d.is_dir() and d.name in {'restored_temperature','restored_humidity','estimated_short_temperature_gaps','estimated_humidity_2022','restored_secondary_sensors'}:
  files += [p for p in d.iterdir() if p.is_file()]
files += [R/'reports/2026-11-13-temperature-interpolation-seasonal-blocks.md',R/'reports/2026-11-13-temperature-interpolation-block-extrema.md',R/'reports/2026-11-13-rh-luhamet-outage-2022-source-coverage.md',R/'reports/2026-11-12-outtemp-source-copy-screening.md',R/'reports/2026-11-12-rh-source-conflicts.md',R/'reports/2026-11-13-historical-weewx-lineage-search.md',R/'reports/2026-11-13-estimated-short-temperature-gap-proposals.md',R/'reports/2026-11-13-rh-winter-reference-validation.md',R/'reports/2026-11-13-rh-winter-local-validation.csv',R/'reports/2026-11-13-rh-winter-monthly-validation.csv',R/'reports/2026-11-13-rh-winter-source-concordance-q1-2019.csv',R/'sql/readonly/rh_winter_local_reference_validation_2018_2020.sql',R/'scripts/validate_rh_winter_reference_validation.py',R/'reports/LOCAL_SIMULATION_REPORT.md',R/'reports/2026-11-13-public-station-history-lineage.md',R/'data/source-lineage/public_station_history_20261113.json',R/'reports/2026-11-13-rh-source-pair-year-epoch-triage.md',R/'reports/2026-11-13-rh-source-pair-year-epoch-triage.csv',R/'reports/2026-11-13-rh-source-pair-interval6-cases.csv',R/'sql/readonly/rh_source_pair_year_epoch_triage.sql',R/'sql/readonly/rh_source_pair_interval6_cases.sql',R/'scripts/validate_rh_source_pair_year_epoch_triage.py']
files=list(dict.fromkeys(p for p in files if p.is_file()))
out=R/'loucka_historical_audit_and_priority_corrections_v1.zip'
internal={'archive':out.name,'status':'FIRST_PRACTICAL_AUDIT_MILESTONE_WITH_LIMITATIONS','required_main_reports':18,'required_report_paths':['reports/'+x['report'] for x in inv['reports']],'required_reports_included':sum((R/'reports'/x['report']).is_file() for x in inv['reports']),'priority_packages':5,'estimated_proposal_timestamps':107,'restored_proposal_candidates':0,'eligible_for_application':0,'limitations':['This is not a full historical reconstruction or publication.','No DB staging, writes, production archive changes, or publication.','Q1 2018 excluded from new proposals; 2021 diagnostic only.'],'contents':[{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in files]}
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
 for p in files:z.write(p,p.relative_to(R).as_posix())
 z.writestr('MANIFEST.json',json.dumps(internal,ensure_ascii=False,indent=2)+'\n')
manifest={'archive':out.name,'status':'FIRST_PRACTICAL_AUDIT_MILESTONE_WITH_LIMITATIONS','files':len(files)+1,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'required_main_reports':18,'required_reports_included':sum((R/'reports'/x['report']).is_file() for x in inv['reports']),'priority_packages':5,'estimated_proposal_timestamps':107,'restored_proposal_candidates':0,'eligible_for_application':0,'limitations':['All five packages are schema-validated; P3 has 107 ESTIMATED proposals with synthetic-holdout limitations; P1/P2/P4/P5 have zero candidates.','This is not a full historical reconstruction or publication.','No DB staging, writes, production archive changes, or publication.','Q1 2018 excluded from new proposals; 2021 diagnostic only.']}
(R/'reports/2026-11-13-priority-milestone-zip-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(manifest,ensure_ascii=False))
